const stages = new Set(['gmail', 'outlook', 'openai', 'supabase', 'calendar', 'line', 'validation', 'orchestrator']);
const sources = new Set(['gmail', 'outlook']);
return $input.all().map((item) => {
  const input = item.json;
  const stage = stages.has(input.stage) ? input.stage : 'orchestrator';
  const source = sources.has(input.source) ? input.source : null;
  const errorCode = String(input.errorCode ?? 'unknown_error').replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 64) || 'unknown_error';
  const allowedSummaries = {
    retry_exhausted: 'External service failed after retry limit',
    authentication_failed: 'External service authentication failed',
    permission_denied: 'External service permission was denied',
    validation_failed: 'Input or response validation failed',
    service_failed: 'External service request failed',
    database_failed: 'Database operation failed'
  };
  const summaryKey = String(input.summaryKey ?? 'service_failed');
  const errorSummary = allowedSummaries[summaryKey] ?? allowedSummaries.service_failed;
  const retryCount = Math.min(3, Math.max(0, Number.parseInt(input.retryCount ?? 0, 10) || 0));
  const safe = { executionId: String(input.executionId ?? '').slice(0, 128) || null, source, messageId: typeof input.messageId === 'string' ? input.messageId.slice(0, 255) : null, mailLogId: typeof input.mailLogId === 'string' ? input.mailLogId : null, stage, errorCode, errorSummary, retryCount };
  console.error(JSON.stringify({ stage: safe.stage, errorCode: safe.errorCode, errorSummary: safe.errorSummary, retryCount: safe.retryCount }));
  return { json: safe };
});

