INSERT INTO error_logs (execution_id, mail_log_id, source, message_id, stage, error_code, error_summary, retry_count, workflow_name, node_name, error_type, error_message, occurred_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'mail-orchestrator', $5, CASE $5 WHEN 'gmail' THEN 'gmail_error' WHEN 'outlook' THEN 'outlook_error' WHEN 'openai' THEN 'openai_error' WHEN 'calendar' THEN 'calendar_error' WHEN 'line' THEN 'line_error' WHEN 'supabase' THEN 'supabase_error' WHEN 'validation' THEN 'validation_error' ELSE 'unknown_error' END, $7, now())
RETURNING id, execution_id AS "executionId", stage, error_code AS "errorCode", retry_count AS "retryCount", occurred_at AS "occurredAt";
